import { publicUrl } from './publicUrl'

/**
 * public/audio/index.json and public/images/cards/index.json list the files that really exist
 * (generated by tools/public_index.mjs). Reading the index means we never request a missing file,
 * so the console stays clean. Resolves to null when the index itself is unavailable.
 */
const cache = new Map<string, Promise<Set<string> | null>>()

export function loadPublicIndex(dir: 'audio' | 'images/cards'): Promise<Set<string> | null> {
  let p = cache.get(dir)
  if (!p) {
    p = fetch(publicUrl(`${dir}/index.json`))
      .then((r) => (r.ok ? r.json() : null))
      .then((j) => (j && Array.isArray(j.files) ? new Set<string>(j.files as string[]) : null))
      .catch(() => null)
    cache.set(dir, p)
  }
  return p
}
